local GameVersion = require("src.core.GameVersion")
GameVersion.set("ruby")
local Dataset = require("src.core.game3.dataset")
Dataset.cacheRootOverride = root
Dataset.mountExtractRoots()
local Space = require("src.core.game3.scripting.space")
Space.bundle = nil
Space.ensureBundle(nil)

local Json = require("src.link.Json")
local MysteryGift = require("src.core.game3.mystery_gift")
local Event = require("src.core.game3.rs.mystery_event")
local IR = require("src.core.game3.scripting.text_ir")
local Bag = require("src.core.game3.bag")
MysteryGift.GIFT_PUBKEY = FIXTURE_PUB

local list = assert(MysteryGift.verifyFeed(Json.decode(FEED_RS), "rs", "ruby"))
local function session()
  return { version = "ruby", bag = Bag.new(), party = {}, flags = {}, vars = {} }
end

print("[test] 1. The relay EON TICKET event runs like the e-Reader card")
local s = session()
local r = Event.run(list.events[1].bytes, s)
check(r.valid, "me_checkcompat accepts the block on Ruby")
-- pokeruby/data/debug_mystery_event_scripts.s:134 setmysteryeventstatus 0x2
eq(r.status, Event.SUCCESS, "the event succeeds")
check(r.save, "and asks for a save")
eq(s.recordMixingGift and s.recordMixingGift.itemId, 275, "the record mixing gift is the EON TICKET")
eq(s.recordMixingGift and s.recordMixingGift.quantity, 5, "five copies spread by record mixing")
check(type(s.ramScriptNativeBytes) == "table" and #s.ramScriptNativeBytes > 0, "Dad's RAM script is installed")
check(IR.toPlain(r.message):find("PETALBURG") ~= nil, "the result says to go see Dad: " .. IR.toPlain(r.message))
Bag.add(s.bag, 275, 1)
local again = Event.run(list.events[1].bytes, s)
-- pokeruby/data/debug_mystery_event_scripts.s:139 setmysteryeventstatus 0x3
eq(again.status, Event.FAILURE, "with the ticket in the bag the event refuses")
check(IR.toPlain(again.message):find("only once") ~= nil, "and says it may be played only once")

print("[test] 2. The ribbon event and the Sapphire header")
local sap = session()
sap.version = "sapphire"
local ribbon = Event.run(list.events[2].bytes, sap)
check(ribbon.valid, "the ribbon block runs on Sapphire")
eq(ribbon.status, Event.SUCCESS, "and succeeds")
local raw = list.events[1].bytes
local rubyOnly = raw:sub(1, 13) .. string.char(0x80, 0, 0, 0) .. raw:sub(18)
local refused = Event.run(rubyOnly, session())
check(refused.valid, "a Ruby-only header runs on Ruby")
local onSapphire = session()
onSapphire.version = "sapphire"
check(not Event.run(rubyOnly, onSapphire).valid, "but not on Sapphire")

print("[test] 3. The Mystery Events screen loads the event from the relay")
do
  local MenuEvents = require("src.ui.game3.rs.mystery_events")
  local transport = { calls = 0 }
  function transport:begin(req) self.calls = self.calls + 1 self.url = req.url return 1 end
  function transport:poll() return { status = "ok", code = 200, body = FEED_RS } end
  function transport:release() end
  local writes = 0
  local ui = MenuEvents.new({ session = session(), transport = transport,
    writeSave = function() writes = writes + 1 return true end })
  local function step(key)
    local inp = { new = {}, held = {} }
    if key then inp.new[key] = true end
    return ui:frame(inp)
  end
  for _ = 1, 2000 do
    if ui.state == "list" or ui.state == "result_print" then break end
    step(ui.printer and ui.printer:isActive() and "a" or nil)
  end
  eq(ui.state, "list", "the relay events are listed")
  check(transport.url and transport.url:find("family=rs", 1, true) and transport.url:find("version=ruby", 1, true),
    "the screen asks the relay for the rs feed: " .. tostring(transport.url))
  eq(#ui.rows, #list.events + 1, "every event and the news entry")
  eq(ui.rows[#ui.rows].kind, "news", "news rides the same list")
  step("a")
  for _ = 1, 4000 do
    if ui.state == "result" then break end
    step((ui.state == "ready" or (ui.printer and ui.printer:isActive())) and "a" or nil)
  end
  eq(ui.state, "result", "the event ran without a link partner")
  eq(ui.result and ui.result.status, Event.SUCCESS, "and succeeded")
  eq(writes, 1, "the save was written once")
  eq(ui.session.recordMixingGift and ui.session.recordMixingGift.itemId, 275, "the session holds the gift")

  local news = MenuEvents.new({ session = session(), transport = transport,
    writeSave = function() writes = writes + 1 return true end })
  ui = news
  for _ = 1, 2000 do
    if ui.state == "list" then break end
    step(ui.printer and ui.printer:isActive() and "a" or nil)
  end
  for _ = 1, #list.events do step("down") end
  step("a")
  eq(ui.state, "news_view", "Ruby opens the WONDER NEWS")
  step("a")
  check(MysteryGift.validateSavedNews(ui.session), "and saves it on the news path")
  check(MysteryGift.hasClaimedNews(ui.session, 9), "the news is claimed")
  eq(writes, 2, "the news save was written")
end

print("[test] 4. Every relay event Pokémon arrives as its PKHeX template")
local catalogPath = os.getenv("POKEPORT_GIFT_EVENTS") or "../pokeserver/gifts_events.json"
local f = io.open(catalogPath, "rb")
local rows = {}
if f then
  rows = Json.decode(f:read("*a"))
  f:close()
else
  print("[skip] " .. catalogPath .. " not found, the full catalog run is skipped")
end
local Base64 = require("src.core.Base64")
local Ribbons = require("src.core.game3.rse.ribbons")
local codec = require("src.save_convert.Gen3Save").forVersion("ruby")
local bit = require("bit")
local seen = 0
for _, row in ipairs(rows) do
  if row.payload then
    seen = seen + 1
    local g = row.gift
    local bytes = Base64.decode(row.payload)
    check(MysteryGift.eventHeaderOk(bytes, "ruby") and MysteryGift.eventHeaderOk(bytes, "sapphire"),
      row.key .. " passes me_checkcompat on both games")
    local s2 = session()
    local res = Event.run(bytes, s2)
    eq(res.status, Event.SUCCESS, row.key .. " succeeds " .. tostring(res.error))
    local mon = s2.party[1]
    local cart = codec.decodePartyMon(bytes:sub(37, 136))
    eq(mon and mon.species, g.species, row.key .. " species")
    if mon and g.kind == "mon" then eq(mon.level, g.level, row.key .. " level") end
    if mon and g.otName then
      local ot = cart.language == 1 and codec.decodeString(cart.otNameRaw, 0, 7, 1, true) or cart.otName
      eq(ot, g.otName, row.key .. " OT in the cart bytes")
    end
    if mon and g.otIdMax then check(mon.otId >= 1 and mon.otId <= g.otIdMax, row.key .. " TID in range")
    elseif mon and g.otId then eq(mon.otId, g.otId, row.key .. " TID") end
    if mon and g.otId and not g.secretIdRandom then eq(mon.otSecretId, 0, row.key .. " SID 0") end
    if mon and g.language then eq(cart.language, g.language, row.key .. " language byte") end
    if mon and (g.otGender == 0 or g.otGender == 1) then eq(cart.otGender, g.otGender, row.key .. " OT gender") end
    if mon then eq(mon.modernFatefulEncounter == true, g.fateful ~= false, row.key .. " fateful flag") end
    if mon and g.nationalRibbon then eq(Ribbons.get(mon, "national"), 1, row.key .. " National Ribbon") end
    if mon and g.movesOnly then
      for slot = 1, 4 do eq(mon.moves[slot], g.moves[tostring(slot)], row.key .. " move " .. slot) end
    end
    if mon and g.shiny ~= "random" then
      local p = mon.personality % 4294967296
      local v = bit.bxor(bit.bxor(mon.otId % 65536, mon.otSecretId % 65536), bit.bxor(math.floor(p / 65536), p % 65536))
      check((v < 8) == (g.shiny == "always"), row.key .. " shiny rule " .. g.shiny)
    end
  end
end
if f then check(seen >= 250, "the RS catalog carries every PKHeX event (" .. seen .. ")") end
local full = session()
for i = 1, 6 do full.party[i] = { species = 1 } end
local refused = Event.run(list.events[3].bytes, full)
eq(refused.status, Event.FAILURE, "a full party refuses the gift")

T.finish("game3_rs_mystery_event_feed")
